"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[[10,15],[6,9],[13,3]],[[5,3],[12,10],[7,0]],[[9,6],[3,15],[14,5]],[[2,11],[11,4],[15,8]],[[4,14],[8,7],[1,10]],[[0,9],[10,6],[6,15]]];
let variant=OrionProgress.variant('xor'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,mask=0,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function bits(n){return n.toString(2).padStart(4,'0');}
function toggle(i){if(solved||!Number.isInteger(i)||i<0||i>3)return;mask^=1<<(3-i);state='ready';render();}
function resetTrial(){mask=0;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('xor')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if((challenge()[0]^mask)!==challenge()[1])state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('switchlight');}render();if(solved&&stage<2)$('next').focus();}
function lamps(n,label){return `<div class="pattern"><strong>${label}</strong><div class="lanterns" aria-label="${label}: ${bits(n)}">${[...bits(n)].map(x=>`<span class="lantern ${x==='1'?'on':''}"><span aria-hidden="true">${x==='1'?'✦':'○'}</span><b>${x}</b></span>`).join('')}</div></div>`;}
function drawing(){return lamps(challenge()[0],t('Incoming lights','傳入燈號'))+`<div class="flow" aria-hidden="true">↓</div>`+lamps(mask,t('Your switches','你的開關'));}
function hints(){const [a,b]=challenge();return[t('Try one switch. Which result light changes? Try it again.','試按一個開關。哪盞結果燈改變？再按一次看看。'),t('Compare each pair: different inputs make 1; matching inputs make 0. This rule is called XOR.','逐對比較：兩個輸入不同，結果是 1；相同，結果是 0。這個規則叫 XOR（互斥或）。'),t(`Set your switches to ${bits(a^b)}, from left to right. A 1 flips the incoming light; a 0 keeps it.`,`由左至右，把開關設為 ${bits(a^b)}。1 會反轉傳入燈號；0 會保留它。`)];}
function render(){const q=challenge(),out=q[0]^mask,complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Twin Lantern Vault · Orion','雙燈寶庫 · Orion');$('stageTitle').textContent=t(`Seal ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道封印 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Lantern seals · ${p} / 3`,`燈號封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();
for(let i=0;i<4;i++){const on=Boolean(mask&(1<<(3-i))),btn=$('bit'+i);btn.disabled=solved;btn.setAttribute('aria-pressed',String(on));btn.setAttribute('aria-label',t(`Switch ${i+1}: ${on?'on':'off'}`,`開關 ${i+1}：${on?'開':'關'}`));btn.textContent=t(`Switch ${i+1} · ${on?'1 ON':'0 OFF'}`,`開關 ${i+1} · ${on?'1 開':'0 關'}`);}
$('goal').innerHTML=lamps(q[1],t('Match this pattern','配對這個燈號'));$('reading').innerHTML=lamps(out,t('Your result','你的結果'));$('reference').textContent=t('1 = light on · 0 = light off','1 = 亮燈 · 0 = 熄燈');const messages={ready:['Tap the four switches. Watch the result, then check the seal.','輕按四個開關，觀察結果，再檢查封印。'],wrong:['Not quite! Compare the result with the target, one light at a time.','還未配對！逐盞比較結果與目標，再試一次。'],success:['The light patterns match! This seal opens.','燈號完全相同！這道封印打開了。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('switchlight')?t('Switchlight Sigil saved in your collection.','轉光符印已存入收藏。'):'';}
for(let i=0;i<4;i++)$('bit'+i).onclick=()=>toggle(i);
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('xor',variant);observedVariant=OrionProgress.variant('xor');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('switchlight');render();};function syncProgress(){const v=OrionProgress.variant('xor'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('switchlight')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
